'use client';
import { useEffect, useState } from 'react';
import toast from 'react-hot-toast';
import { RefreshCw, Plus, Trash2, Database, AlertCircle } from 'lucide-react';

export default function LeagueManagerPage() {
  const [configs, setConfigs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);

  const [newConfig, setNewConfig] = useState({
    season_year: 2026,
    team_name: '',
    ladder_url: '',
    fixtures_url: ''
  });

  const fetchConfigs = async () => {
    try {
      const res = await fetch('http://localhost:5001/api/league/configs');
      const data = await res.json();
      setConfigs(Array.isArray(data) ? data : []);
    } catch (err) {
      toast.error("Failed to load configurations");
    }
  };

  useEffect(() => { fetchConfigs(); }, []);

  const handleCreateConfig = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch('http://localhost:5001/api/league/configs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newConfig),
      });

      if (!res.ok) throw new Error("Failed to save config");

      toast.success("Season Added!");
      setNewConfig({ season_year: 2026, team_name: '', ladder_url: '', fixtures_url: '' });
      setShowForm(false);
      fetchConfigs();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure? This will remove the config (but keep cached data until next sync).")) return;
    
    try {
      const res = await fetch(`http://localhost:5001/api/league/configs/${id}`, {
        method: 'DELETE'
      });
      if (res.ok) {
        toast.success("Deleted");
        fetchConfigs();
      }
    } catch (err) {
      toast.error("Delete failed");
    }
  };

  const triggerSync = async (id: string) => {
    setLoading(true);
    const loadToast = toast.loading("Scraping GameDay data...");
    try {
      const res = await fetch(`http://localhost:5001/api/scraper/sync/${id}`, {
        method: 'POST'
      });
      if (!res.ok) throw new Error("Sync failed");
      toast.success("Database Updated Successfully", { id: loadToast });
    } catch (err) {
      toast.error("Sync Error", { id: loadToast });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 bg-[#020617] min-h-screen text-white font-sans">
      <div className="max-w-5xl mx-auto">
        <header className="flex justify-between items-center mb-12">
          <div>
            <h1 className="text-4xl font-black uppercase italic tracking-tighter italic">
              League <span className="text-red-600">Control</span>
            </h1>
            <p className="text-slate-500 text-[10px] font-mono mt-2 uppercase tracking-[0.3em]">
              Centralized Season Management
            </p>
          </div>
          <button 
            onClick={() => setShowForm(!showForm)}
            className="bg-red-600 text-white px-6 py-3 rounded-full font-black uppercase text-[10px] tracking-widest flex items-center gap-2 hover:bg-white hover:text-black transition-all shadow-lg shadow-red-900/20"
          >
            {showForm ? 'Cancel' : <><Plus size={14} /> Add Season</>}
          </button>
        </header>

        {showForm && (
          <form onSubmit={handleCreateConfig} className="mb-12 p-8 bg-slate-900/50 rounded-[2rem] border border-slate-800 grid grid-cols-2 gap-6 backdrop-blur-sm">
            <div className="col-span-1">
              <label className="text-[10px] font-black uppercase text-slate-500 mb-2 block ml-1">Season Year</label>
              <input required type="number" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-2xl focus:border-red-600 outline-none transition-colors" value={newConfig.season_year} onChange={e => setNewConfig({...newConfig, season_year: parseInt(e.target.value)})} />
            </div>
            <div className="col-span-1">
              <label className="text-[10px] font-black uppercase text-slate-500 mb-2 block ml-1">Team Name</label>
              <input required placeholder="e.g. Senior Men" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-2xl focus:border-red-600 outline-none transition-colors" value={newConfig.team_name} onChange={e => setNewConfig({...newConfig, team_name: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className="text-[10px] font-black uppercase text-red-500/50 mb-2 block ml-1">GameDay Ladder URL</label>
              <input required type="url" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-2xl focus:border-red-600 outline-none text-xs font-mono" value={newConfig.ladder_url} onChange={e => setNewConfig({...newConfig, ladder_url: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className="text-[10px] font-black uppercase text-red-500/50 mb-2 block ml-1">GameDay Fixtures URL</label>
              <input required type="url" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-2xl focus:border-red-600 outline-none text-xs font-mono" value={newConfig.fixtures_url} onChange={e => setNewConfig({...newConfig, fixtures_url: e.target.value})} />
            </div>
            <button disabled={loading} type="submit" className="col-span-2 bg-white text-black p-5 rounded-2xl font-black uppercase text-xs tracking-[0.2em] hover:bg-red-600 hover:text-white transition-all">
              {loading ? 'Processing...' : 'Save Configuration'}
            </button>
          </form>
        )}

        <div className="grid gap-4">
          {configs.length === 0 && !loading && (
            <div className="text-center py-20 border-2 border-dashed border-slate-800 rounded-[3rem]">
              <AlertCircle className="mx-auto text-slate-700 mb-4" size={40} />
              <p className="text-slate-500 uppercase font-black text-xs tracking-widest">No seasons configured yet</p>
            </div>
          )}
          {configs.map((config: any) => (
            <div key={config.id} className="group bg-slate-900/40 border border-slate-800 p-6 rounded-[2.5rem] flex items-center justify-between hover:border-slate-600 transition-all">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-slate-950 rounded-2xl flex items-center justify-center border border-slate-800 group-hover:border-red-600 transition-colors shadow-inner">
                  <Database size={20} className="text-slate-500 group-hover:text-red-600" />
                </div>
                <div>
                  <h3 className="text-xl font-black uppercase italic tracking-tight">{config.season_year} <span className="text-slate-500">{config.team_name}</span></h3>
                  <div className="flex gap-4 mt-2">
                    <span className="text-[9px] font-bold text-slate-600 bg-slate-950 px-3 py-1 rounded-full border border-slate-800">SOURCE: GAMEDAY</span>
                  </div>
                </div>
              </div>
              
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => triggerSync(config.id)}
                  disabled={loading}
                  className="bg-slate-800 hover:bg-red-600 px-6 py-3 rounded-xl flex items-center gap-3 transition-all"
                >
                  <RefreshCw size={14} className={loading ? "animate-spin" : ""} />
                  <span className="text-[10px] font-black uppercase tracking-widest">Sync</span>
                </button>
                <button 
                  onClick={() => handleDelete(config.id)}
                  className="p-3 bg-slate-950 border border-slate-800 rounded-xl hover:bg-red-900/20 hover:border-red-900 text-slate-600 hover:text-red-500 transition-all"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}